(2133241, 291453, 49480, '<td valign="top">Beautiful, but not motion panning.</td>', 'Beautiful, but not motion panning.', '2006-02-08 09:23:25.000000', NULL, 1),
(2133242, 291885, 42506, '<td valign="top">One of the better shots so far. Good job. Personally I would like to see a touch more darkness / contrast through the colours but this got a 7 from me.</td>', 'One of the better shots so far. Good job. Personally I would like to see a touch more darkness / contrast through the colours but this got a 7 from me.', '2006-02-08 09:23:36.000000', NULL, 1),
(2133243, 290689, 52091, '<td valign="top">Very clear. good composition,</td>', 'Very clear. good composition,', '2006-02-08 09:23:41.000000', NULL, 1),
(2133247, 292748, 52091, '<td valign="top">Nice composition. Next tim try a different angle.</td>', 'Nice composition. Next tim try a different angle.', '2006-02-08 09:24:26.000000', NULL, 1),
(2133249, 290777, 42506, '<td valign="top">Good attempt. Stuck with this difficult challenge and I think this is a decent shot.</td>', 'Good attempt. Stuck with this difficult challenge and I think this is a decent shot.', '2006-02-08 09:25:00.000000', NULL, 1),
(2133255, 292803, 42506, '<td valign="top">Nice - I like this</td>', 'Nice - I like this', '2006-02-08 09:27:03.000000', NULL, 1),
