(2133271, 291237, 52091, '<td valign="top">Nice use of space. Try to darken the image a little next time.</td>', 'Nice use of space. Try to darken the image a little next time.', '2006-02-08 09:32:06.000000', NULL, 1),
(2133274, 292337, 52091, '<td valign="top">Nice angle. Very clear photo.</td>', 'Nice angle. Very clear photo.', '2006-02-08 09:32:39.000000', NULL, 1),
(2133275, 292852, 52091, '<td valign="top">Nice composition. Great angle!</td>', 'Nice composition. Great angle!', '2006-02-08 09:33:12.000000', NULL, 1),
(2133277, 290135, 42506, '<td valign="top">Great atmosphere. Good entry in this challenge.</td>', 'Great atmosphere. Good entry in this challenge.', '2006-02-08 09:33:35.000000', NULL, 1),
