(2133283, 291453, 52589, '<td valign="top">Superb photo... but not quite ''motion panning'' in my books.</td>', 'Superb photo... but not quite ''motion panning'' in my books.', '2006-02-08 09:35:18.000000', NULL, 1),
(2133284, 292536, 52091, '<td valign="top">Good composition. Very sharp.</td>', 'Good composition. Very sharp.', '2006-02-08 09:35:51.000000', NULL, 1),
(2133287, 290777, 52091, '<td valign="top">Love how sharp and clear the image is. Nxt time shoot at another angle.</td>', 'Love how sharp and clear the image is. Nxt time shoot at another angle.', '2006-02-08 09:37:23.000000', NULL, 1),
(2133288, 292854, 52091, '<td valign="top">Like how the subject is very sharp.</td>', 'Like how the subject is very sharp.', '2006-02-08 09:38:53.000000', NULL, 1),
(2133289, 292264, 30841, '<td valign="top">This is an amazing shot. Not only did the car remain out of blur, but so does the lines on the strip, and the two walls. Great Job.</td>', 'This is an amazing shot. Not only did the car remain out of blur, but so does the lines on the strip, and the two walls. Great Job.', '2006-02-08 09:39:29.000000', NULL, 1),
