(2134373, 291519, 52928, '<td valign="top">Good vantage point to keep the background simple.  The bird is sharp and you''ve left space for it to fly into.  The conversion to B&amp;W also seems to work well. Good technique.</td>', 'Good vantage point to keep the background simple.  The bird is sharp and you''ve left space for it to fly into.  The conversion to B&W also seems to work well. Good technique.', '2006-02-08 14:46:33.000000', NULL, 1),
(2134376, 292016, 44490, '<td valign="top">Pretty good attempt at a difficult challenge.  Unfortunately it''s difficult to show off motion panning with people walking - the walk is not fast enough to blur the background much, and the motion is too complex for a sharp subject.</td>', 'Pretty good attempt at a difficult challenge.  Unfortunately it''s difficult to show off motion panning with people walking - the walk is not fast enough to blur the background much, and the motion is too complex for a sharp subject.', '2006-02-08 14:47:40.000000', NULL, 1),
(2134378, 291920, 51122, '<td valign="top">i like how the background accents the subject...brilliant!</td>', 'i like how the background accents the subject...brilliant!', '2006-02-08 14:47:58.000000', NULL, 1),
(2134379, 292775, 52928, '<td valign="top">The jumper is sharp and their shadow adds to the sense of distance from the ground.   Would have preferred to see them from more in front though.  Good panning technique.</td>', 'The jumper is sharp and their shadow adds to the sense of distance from the ground.   Would have preferred to see them from more in front though.  Good panning technique.', '2006-02-08 14:48:06.000000', NULL, 1),
(2134382, 289925, 52928, '<td valign="top">The car is sharp and the positioning in from of the VEGAS sign is well executed. Good technique.</td>', 'The car is sharp and the positioning in from of the VEGAS sign is well executed. Good technique.', '2006-02-08 14:48:53.000000', NULL, 1),
(2134385, 291885, 52928, '<td valign="top">Sharp focus on the car, though unfortunate that you got the picture from the side that is in shadow.  Good panning technique though.</td>', 'Sharp focus on the car, though unfortunate that you got the picture from the side that is in shadow.  Good panning technique though.', '2006-02-08 14:49:57.000000', NULL, 1),
(2134387, 292337, 51122, '<td valign="top">i love the clarity of the colour on the car (subject)...it makes u wanna look at the car and look at it again, and agian, and again...</td>', 'i love the clarity of the colour on the car (subject)...it makes u wanna look at the car and look at it again, and agian, and again...', '2006-02-08 14:50:21.000000', NULL, 1),
