INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2139123, 292498, 37320, '<td valign="top">I have that shirt!  (not the kid size)   Just for that you get a 10!</td>', 'I have that shirt!  (not the kid size)   Just for that you get a 10!', '2006-02-10 02:24:51.000000', NULL, 1),
(2139125, 291157, 37320, '<td valign="top">Sharp Focus.  A cowboy hat  or a bandana would make it exponentially better.</td>', 'Sharp Focus.  A cowboy hat  or a bandana would make it exponentially better.', '2006-02-10 02:26:07.000000', NULL, 1),
(2139135, 292550, 37320, '<td valign="top">-Good capture, interesting DOF, nice subtle colors.<br/>The title adds some fun to this photo, just promise me you didn''t give the dog some cheesy Disney name, like "Chance" or "Shadow".</td>', '-Good capture, interesting DOF, nice subtle colors.The title adds some fun to this photo, just promise me you didn''t give the dog some cheesy Disney name, like "Chance" or "Shadow".', '2006-02-10 02:32:55.000000', NULL, 1),
(2139145, 292854, 37320, '<td valign="top">Very cool. This stands out as both a great portrait and a fine pan.  A ten from me.</td>', 'Very cool. This stands out as both a great portrait and a fine pan.  A ten from me.', '2006-02-10 02:38:51.000000', NULL, 1),
(2139174, 292854, 44242, '<td valign="top">Good job. Meets the challenge. Great subject sharpness and Background Blur.</td>', 'Good job. Meets the challenge. Great subject sharpness and Background Blur.', '2006-02-10 03:11:16.000000', NULL, 1),
(2139176, 292264, 44242, '<td valign="top">True panning, so scores well from me! Good subject sharpness, and blur. subject centered and small detracts a little.</td>', 'True panning, so scores well from me! Good subject sharpness, and blur. subject centered and small detracts a little.', '2006-02-10 03:12:32.000000', NULL, 1),
(2139177, 292441, 44242, '<td valign="top">Second time voting. True panning, so scores well from me!</td>', 'Second time voting. True panning, so scores well from me!', '2006-02-10 03:13:05.000000', NULL, 1),
(2139179, 292134, 44242, '<td valign="top">Great subject and capture. Good tracking and subject sharpness. Panning is a little subtle though given how fast the subject must be moving. Could have captured a longer blur. Great shot.</td>', 'Great subject and capture. Good tracking and subject sharpness. Panning is a little subtle though given how fast the subject must be moving. Could have captured a longer blur. Great shot.', '2006-02-10 03:14:12.000000', NULL, 1),
(2139182, 290765, 44242, '<td valign="top">Good to see some real panning (after voting once already can see how few people understood the challenge. Nice composition and tilt. Good blur, and subject sharpness.</td>', 'Good to see some real panning (after voting once already can see how few people understood the challenge. Nice composition and tilt. Good blur, and subject sharpness.', '2006-02-10 03:15:03.000000', NULL, 1),
(2139183, 292821, 44242, '<td valign="top">Good pan. Captures the movement very well, and the subject blur is ok given the nature of the subject...adds to dynamism!</td>', 'Good pan. Captures the movement very well, and the subject blur is ok given the nature of the subject...adds to dynamism!', '2006-02-10 03:15:44.000000', NULL, 1),
(2139185, 290668, 44242, '<td valign="top">Good creative pan.</td>', 'Good creative pan.', '2006-02-10 03:16:08.000000', NULL, 1),
(2139186, 291519, 44242, '<td valign="top">Difficult subject. Well caputured. True panning.</td>', 'Difficult subject. Well caputured. True panning.', '2006-02-10 03:16:37.000000', NULL, 1),
(2139187, 291947, 44242, '<td valign="top">Great capture. True panning. The tilt makes me a little uncomfortable... have to rotate my head to balance... but one of the better pans in the challenge.</td>', 'Great capture. True panning. The tilt makes me a little uncomfortable... have to rotate my head to balance... but one of the better pans in the challenge.', '2006-02-10 03:18:06.000000', NULL, 1),
(2139191, 289925, 44242, '<td valign="top">True panning, so scores well compared to many in challenge from me. Given the speed of the subject, the out of motion blur could easily have been much more striking, but It works with the background text still readable. Good shot.</td>', 'True panning, so scores well compared to many in challenge from me. Given the speed of the subject, the out of motion blur could easily have been much more striking, but It works with the background text still readable. Good shot.', '2006-02-10 03:19:23.000000', NULL, 1),
(2139193, 291370, 44242, '<td valign="top">Difficult subject. Well captured.. true panning! (I have to say this given how many people did not meet the challenge) Well done.</td>', 'Difficult subject. Well captured.. true panning! (I have to say this given how many people did not meet the challenge) Well done.', '2006-02-10 03:20:12.000000', NULL, 1),
(2139197, 291237, 44242, '<td valign="top">Very nice shot. Looks like it could have been taken from moving vehicle, but I''m definitely going to give you the benefit of the doubt and score well.</td>', 'Very nice shot. Looks like it could have been taken from moving vehicle, but I''m definitely going to give you the benefit of the doubt and score well.', '2006-02-10 03:21:55.000000', NULL, 1),
(2139201, 290689, 44242, '<td valign="top">yep... that''s panning! Am revoting and bumping up those that are obviously REALLY panning.</td>', 'yep... that''s panning! Am revoting and bumping up those that are obviously REALLY panning.', '2006-02-10 03:23:23.000000', NULL, 1),
(2139206, 292451, 44242, '<td valign="top">Awesome shot. composition bit tight up top, but don''t know how much room you have to play with there, or if that was a deliberate choice. The fact that the car is breaking, really adds drama to the subject sharpness. Just a pity there wasn''t more textured background to blur. High score from me.</td>', 'Awesome shot. composition bit tight up top, but don''t know how much room you have to play with there, or if that was a deliberate choice. The fact that the car is breaking, really adds drama to the subject sharpness. Just a pity there wasn''t more textured background to blur. High score from me.', '2006-02-10 03:25:02.000000', NULL, 1),
(2139207, 290580, 44242, '<td valign="top">Great color... good subject sharpness and background blur. very nice!</td>', 'Great color... good subject sharpness and background blur. very nice!', '2006-02-10 03:25:33.000000', NULL, 1),
(2139210, 292775, 44242, '<td valign="top">Good travel and steadiness with shutter open! Would have been perfect if could have seen front side of body, but this must have been difficult. Very nice.</td>', 'Good travel and steadiness with shutter open! Would have been perfect if could have seen front side of body, but this must have been difficult. Very nice.', '2006-02-10 03:26:30.000000', NULL, 1),
(2139213, 292815, 44242, '<td valign="top">Very appealing. Great sense of movement.</td>', 'Very appealing. Great sense of movement.', '2006-02-10 03:27:40.000000', NULL, 1),
(2139215, 292338, 44242, '<td valign="top">Very nice and dramatic textured background blur. loss of sharpness on the girl is ok in this case, as it adds to the drama / movement. Good shot.</td>', 'Very nice and dramatic textured background blur. loss of sharpness on the girl is ok in this case, as it adds to the drama / movement. Good shot.', '2006-02-10 03:28:54.000000', NULL, 1),
(2139222, 291332, 44242, '<td valign="top">This shot is great. Motion blur, and subject blur work well together in this case.</td>', 'This shot is great. Motion blur, and subject blur work well together in this case.', '2006-02-10 03:30:26.000000', NULL, 1),
(2139225, 292573, 44242, '<td valign="top">Great sense of movement. Good panning technique. We''re a little bit blindsided without seeing the subjects face though. nice shot.</td>', 'Great sense of movement. Good panning technique. We''re a little bit blindsided without seeing the subjects face though. nice shot.', '2006-02-10 03:31:05.000000', NULL, 1),
(2139229, 291067, 44242, '<td valign="top">This is good panning. Great subject sharpness, and shutter must have been open for a while as good limb movement adding to the drama of the approach.</td>', 'This is good panning. Great subject sharpness, and shutter must have been open for a while as good limb movement adding to the drama of the approach.', '2006-02-10 03:32:18.000000', NULL, 1),
(2139232, 292852, 44242, '<td valign="top">The motion blur is very soft and appealing on this shot. Well done.</td>', 'The motion blur is very soft and appealing on this shot. Well done.', '2006-02-10 03:32:51.000000', NULL, 1),
(2139233, 290844, 44242, '<td valign="top">This meets the challenge, but with such a fast smooth object, the motion blur could have been very dramatic. Scores well from me as so many didn''t even meet the challenge.</td>', 'This meets the challenge, but with such a fast smooth object, the motion blur could have been very dramatic. Scores well from me as so many didn''t even meet the challenge.', '2006-02-10 03:33:47.000000', NULL, 1),
(2139235, 292812, 44242, '<td valign="top">One of the most beautiful shots. Great colors and subject sharpness.</td>', 'One of the most beautiful shots. Great colors and subject sharpness.', '2006-02-10 03:35:40.000000', NULL, 1),
(2139236, 292714, 44242, '<td valign="top">Very good panning technique. Obviously you will have already received enough comments about the blown highlights... but I''m still scoring well as you met the challenge (true panning), which is tough... and so many DNMC</td>', 'Very good panning technique. Obviously you will have already received enough comments about the blown highlights... but I''m still scoring well as you met the challenge (true panning), which is tough... and so many DNMC', '2006-02-10 03:36:34.000000', NULL, 1),
(2139241, 291529, 44242, '<td valign="top">Second time voting... not sure if earlier comment about taken from a vehicle was correct, so giving benefit of doubt and levelling the score. Good subject sharpness.</td>', 'Second time voting... not sure if earlier comment about taken from a vehicle was correct, so giving benefit of doubt and levelling the score. Good subject sharpness.', '2006-02-10 03:41:35.000000', NULL, 1),
(2139242, 292550, 44242, '<td valign="top">Good panning technique. Loss of detail on main subject a shame. Nice shot.</td>', 'Good panning technique. Loss of detail on main subject a shame. Nice shot.', '2006-02-10 03:43:06.000000', NULL, 1),
(2139243, 292748, 44242, '<td valign="top">Good sense of speed, and subject sharpness.</td>', 'Good sense of speed, and subject sharpness.', '2006-02-10 03:43:31.000000', NULL, 1),
(2139244, 292097, 44242, '<td valign="top">Good sense of speed.</td>', 'Good sense of speed.', '2006-02-10 03:43:50.000000', NULL, 1),
(2139245, 291037, 44242, '<td valign="top">Panning is subtle, but there... which is more than most in this challenge!</td>', 'Panning is subtle, but there... which is more than most in this challenge!', '2006-02-10 03:44:30.000000', NULL, 1),
(2139246, 290813, 44242, '<td valign="top">Very good sense of motion and speed.</td>', 'Very good sense of motion and speed.', '2006-02-10 03:44:44.000000', NULL, 1),
(2139247, 292336, 44242, '<td valign="top">Third Taxi shot so far... :) and this is the best.</td>', 'Third Taxi shot so far... :) and this is the best.', '2006-02-10 03:45:26.000000', NULL, 1),
(2139250, 290135, 44242, '<td valign="top">Good capture. About as good as you were going to get with a subject moving in curved path.</td>', 'Good capture. About as good as you were going to get with a subject moving in curved path.', '2006-02-10 03:46:21.000000', NULL, 1),
(2139251, 291729, 44242, '<td valign="top">I''ve been waiting for the balloons... and here they are! good sense of motion.</td>', 'I''ve been waiting for the balloons... and here they are! good sense of motion.', '2006-02-10 03:47:11.000000', NULL, 1),
(2139253, 292403, 44242, '<td valign="top">Good points for meeting the challenge, and panning. Subject blur probably won''t help you with voters, bit I like the action.</td>', 'Good points for meeting the challenge, and panning. Subject blur probably won''t help you with voters, bit I like the action.', '2006-02-10 03:47:54.000000', NULL, 1),
(2139254, 292631, 44242, '<td valign="top">Cood subject and pose. The movement is good, but lacks that one key part of the subject in perfect sharpness which is needed to really nail this challenge. Good score for meeting the challenge!</td>', 'Cood subject and pose. The movement is good, but lacks that one key part of the subject in perfect sharpness which is needed to really nail this challenge. Good score for meeting the challenge!', '2006-02-10 03:48:39.000000', NULL, 1),
(2139255, 291606, 44242, '<td valign="top">Good sharpness on the most important part of the image... the leading edge of the subject. Nice.</td>', 'Good sharpness on the most important part of the image... the leading edge of the subject. Nice.', '2006-02-10 03:49:13.000000', NULL, 1),
(2139256, 291195, 44242, '<td valign="top">The panning is there, but the subject cluttered frame take away from the ''tracked'' subject. I know this is hard, so good points for panning.</td>', 'The panning is there, but the subject cluttered frame take away from the ''tracked'' subject. I know this is hard, so good points for panning.', '2006-02-10 03:50:03.000000', NULL, 1),
(2139257, 292626, 44242, '<td valign="top">Good panning. great expressions.</td>', 'Good panning. great expressions.', '2006-02-10 03:50:39.000000', NULL, 1),
(2139258, 292502, 44242, '<td valign="top">Sense of movement is definitely there.  Nice job.</td>', 'Sense of movement is definitely there.  Nice job.', '2006-02-10 03:51:21.000000', NULL, 1),
(2139261, 292224, 44242, '<td valign="top">whoa!! well tracked.. good technique. single point of sharpness on the leading subject is right on. well done.</td>', 'whoa!! well tracked.. good technique. single point of sharpness on the leading subject is right on. well done.', '2006-02-10 03:52:08.000000', NULL, 1),
(2139262, 292764, 44242, '<td valign="top">Good movement. Definitely some panning going on :) and the flapping adds some drama.</td>', 'Good movement. Definitely some panning going on :) and the flapping adds some drama.', '2006-02-10 03:52:49.000000', NULL, 1),
(2139265, 292206, 44242, '<td valign="top">I find this shot very appealing. i like the softness on the subject, as well as the motion blur. Gives a great sense of twilight even without the title. Only comment, is that the composition is a little centred.. I know this is overstated rule but I think it applies in this case.Nicely done.</td>', 'I find this shot very appealing. i like the softness on the subject, as well as the motion blur. Gives a great sense of twilight even without the title. Only comment, is that the composition is a little centred.. I know this is overstated rule but I think it applies in this case.Nicely done.', '2006-02-10 03:54:36.000000', NULL, 1),
(2139266, 292824, 44242, '<td valign="top">Interesting as this is as much coming into the scene, as it is panning. I like the sense of movement.</td>', 'Interesting as this is as much coming into the scene, as it is panning. I like the sense of movement.', '2006-02-10 03:55:02.000000', NULL, 1),
(2139267, 292140, 44242, '<td valign="top">interesting take on panning... but valid, and well taken.</td>', 'interesting take on panning... but valid, and well taken.', '2006-02-10 03:55:29.000000', NULL, 1),
(2139268, 290609, 44242, '<td valign="top">Good focus on leading edge of tracked subject, with room to move into the picture. Good technique, nice capture or crop.</td>', 'Good focus on leading edge of tracked subject, with room to move into the picture. Good technique, nice capture or crop.', '2006-02-10 03:56:07.000000', NULL, 1),
(2139269, 291690, 44242, '<td valign="top">Looks like the subject is breaking teh speed of light. How did you get that effect?</td>', 'Looks like the subject is breaking teh speed of light. How did you get that effect?', '2006-02-10 03:56:39.000000', NULL, 1),
(2139270, 290777, 44242, '<td valign="top">Looks like this kid is heading for an accident! Good panning technique.</td>', 'Looks like this kid is heading for an accident! Good panning technique.', '2006-02-10 03:57:03.000000', NULL, 1),
(2139274, 292756, 44242, '<td valign="top">I know this technique is very hard, so well done. Best subject sharpness and motion blur is usually at point when object is right in front of you, or just approaching, to see the front side of the subject.</td>', 'I know this technique is very hard, so well done. Best subject sharpness and motion blur is usually at point when object is right in front of you, or just approaching, to see the front side of the subject.', '2006-02-10 04:04:55.000000', NULL, 1),
(2139275, 290393, 52578, '<td valign="top">It''s alright but I feel the picture lacks any real center point of focus, I''m sure this is the way you wanted it but to me it doesn''t really work out that great.</td>', 'It''s alright but I feel the picture lacks any real center point of focus, I''m sure this is the way you wanted it but to me it doesn''t really work out that great.', '2006-02-10 04:06:51.000000', NULL, 1),
(2139278, 292336, 52578, '<td valign="top">Cool panning, if the cab stood out more by having more light on it (from another car''s headlights or flash) the picture would be even better imo.</td>', 'Cool panning, if the cab stood out more by having more light on it (from another car''s headlights or flash) the picture would be even better imo.', '2006-02-10 04:12:45.000000', NULL, 1),
(2139279, 292599, 52578, '<td valign="top">There is a lack of motion panning, even though from the snow spray you can see that there is "motion"...  perhaps a slower shutter speed with a skier moving across the frame would''ve worked better.</td>', 'There is a lack of motion panning, even though from the snow spray you can see that there is "motion"...  perhaps a slower shutter speed with a skier moving across the frame would''ve worked better.', '2006-02-10 04:20:11.000000', NULL, 1),
(2139281, 291994, 52578, '<td valign="top">i like the shot for the challenge because there is some motion... but there seems to be a slight lack of sharpness to it, and maybe the sun is just a bit to intense, and the bottom is cropped off a bit early.</td>', 'i like the shot for the challenge because there is some motion... but there seems to be a slight lack of sharpness to it, and maybe the sun is just a bit to intense, and the bottom is cropped off a bit early.', '2006-02-10 04:24:12.000000', NULL, 1),
(2139302, 290668, 48545, '<td valign="top">A nice studio(ish) photo, the marble is perfect, if I had one critisism it would be that the background is a little off putting, the white streaks are almost more powerful than the marble itself</td>', 'A nice studio(ish) photo, the marble is perfect, if I had one critisism it would be that the background is a little off putting, the white streaks are almost more powerful than the marble itself', '2006-02-10 04:50:22.000000', NULL, 1),
(2139305, 291729, 48545, '<td valign="top">nice image, think this might be the one and only vertical panned shot, good idea and good subject for the vertical pan.</td>', 'nice image, think this might be the one and only vertical panned shot, good idea and good subject for the vertical pan.', '2006-02-10 04:52:50.000000', NULL, 1),
(2139318, 291434, 46758, '<td valign="top">Very well done. Very difficult to get that dart sharp into flight, because it is so small. Curious how you did it (tried it myself, but totally failed, I sent it in anyway for comments that could possibly help me). 9.</td>', 'Very well done. Very difficult to get that dart sharp into flight, because it is so small. Curious how you did it (tried it myself, but totally failed, I sent it in anyway for comments that could possibly help me). 9.', '2006-02-10 05:31:33.000000', NULL, 1),
