(2146788, 292322, 52578, '<td valign="top">There is movement but nothing to really grab the attention of the viewer.</td>', 'There is movement but nothing to really grab the attention of the viewer.', '2006-02-13 07:58:59.000000', NULL, 1),
(2146789, 292536, 52578, '<td valign="top">Doesn''t seem to be any motion panning going on.</td>', 'Doesn''t seem to be any motion panning going on.', '2006-02-13 07:59:42.000000', NULL, 1),
(2146807, 292854, 28299, '<td valign="top">This was a tough assignment, but you captured her motion very well. 8</td>', 'This was a tough assignment, but you captured her motion very well. 8', '2006-02-13 08:09:51.000000', NULL, 1),
(2146810, 290765, 28299, '<td valign="top">Well done; very nice clarity on the moving "object/subject!"</td>', 'Well done; very nice clarity on the moving "object/subject!"', '2006-02-13 08:11:07.000000', NULL, 1),
(2147086, 290432, 17505, '<td valign="top">I believe the camera needs to move for the photo to qualify for a ''pan''. You''ve captured motion blur, but not panning.</td>', 'I believe the camera needs to move for the photo to qualify for a ''pan''. You''ve captured motion blur, but not panning.', '2006-02-13 10:14:53.000000', NULL, 1),
(2147119, 292264, 20889, '<td valign="top">I have had always liked drag racing. The first time I took a picture of them going by was all a blur, but I didn''t know anything about motion panning either. I think you did very well considering the speed these monster run. A 10.</td>', 'I have had always liked drag racing. The first time I took a picture of them going by was all a blur, but I didn''t know anything about motion panning either. I think you did very well considering the speed these monster run. A 10.', '2006-02-13 10:33:43.000000', NULL, 1),
(2147120, 292441, 20889, '<td valign="top">My only distraction is the cone in front other than that very nice shot.</td>', 'My only distraction is the cone in front other than that very nice shot.', '2006-02-13 10:35:02.000000', NULL, 1),
(2147122, 290668, 20889, '<td valign="top">Sure is different :-)</td>', 'Sure is different :-)', '2006-02-13 10:36:18.000000', NULL, 1),
(2147126, 292451, 20889, '<td valign="top">Looks like he''s not the only one that has locked it up here, by looking at the track.</td>', 'Looks like he''s not the only one that has locked it up here, by looking at the track.', '2006-02-13 10:38:47.000000', NULL, 1),
(2147130, 291920, 52578, '<td valign="top">Great pan with lots of motion.</td>', 'Great pan with lots of motion.', '2006-02-13 10:42:40.000000', NULL, 1),
(2147131, 291951, 52578, '<td valign="top">Not quite enough movement imo. I can see the wheel blurred just slightly but the background is still very sharp.</td>', 'Not quite enough movement imo. I can see the wheel blurred just slightly but the background is still very sharp.', '2006-02-13 10:43:47.000000', NULL, 1),
