(2147205, 292812, 53095, '<td valign="top">Very nice effect.</td>', 'Very nice effect.', '2006-02-13 11:23:28.000000', NULL, 1),
(2147541, 292796, 13077, '<td valign="top">Pretty good job of panning for that low of a shutter speed. It''s good as an art photo, but as a sports photo not so good. Still, I like the blurred background a lot, although the light streaks are a little distracting.</td>', 'Pretty good job of panning for that low of a shutter speed. It''s good as an art photo, but as a sports photo not so good. Still, I like the blurred background a lot, although the light streaks are a little distracting.', '2006-02-13 14:21:01.000000', NULL, 1),
(2147550, 292854, 13077, '<td valign="top">Great photo. Really nice panning effect, I like how the tip of her hair is blurred as the wind catches it, and the composition and her expression are very good. I think this one should ribbon - 8</td>', 'Great photo. Really nice panning effect, I like how the tip of her hair is blurred as the wind catches it, and the composition and her expression are very good. I think this one should ribbon - 8', '2006-02-13 14:24:25.000000', NULL, 1),
(2147552, 291434, 13077, '<td valign="top">Nice shot. Clean, simple, nice looking backgrounds. Great panning effect also.</td>', 'Nice shot. Clean, simple, nice looking backgrounds. Great panning effect also.', '2006-02-13 14:25:37.000000', NULL, 1),
(2147554, 291947, 13077, '<td valign="top">Very well done. Excellent job on panning, and I like the angle of the shot very much. The background looks great too.</td>', 'Very well done. Excellent job on panning, and I like the angle of the shot very much. The background looks great too.', '2006-02-13 14:27:08.000000', NULL, 1),
(2147558, 292502, 13077, '<td valign="top">Nicely done. It''s a shame there wasn''t a little more light on the rider. And since he''s geared up I''m guessing it was a track - why no shot of one of the jumps?</td>', 'Nicely done. It''s a shame there wasn''t a little more light on the rider. And since he''s geared up I''m guessing it was a track - why no shot of one of the jumps?', '2006-02-13 14:29:44.000000', NULL, 1),
(2147600, 292568, 52578, '<td valign="top">Can''t really see what is going on here. Is it a dart?</td>', 'Can''t really see what is going on here. Is it a dart?', '2006-02-13 14:50:24.000000', NULL, 1),
(2147604, 292426, 52578, '<td valign="top">Not enough motion imo... seems like it is uniformly unsharp.</td>', 'Not enough motion imo... seems like it is uniformly unsharp.', '2006-02-13 14:52:30.000000', NULL, 1),
(2147609, 290541, 52578, '<td valign="top">No panning seems to be involved.</td>', 'No panning seems to be involved.', '2006-02-13 14:55:38.000000', NULL, 1),
(2147610, 292240, 52578, '<td valign="top">Needs a slightly slower shutter speed to get more motion blur.</td>', 'Needs a slightly slower shutter speed to get more motion blur.', '2006-02-13 14:56:07.000000', NULL, 1),
(2147614, 291157, 52578, '<td valign="top">Cool pan... just wish there was a bit more color in the background.</td>', 'Cool pan... just wish there was a bit more color in the background.', '2006-02-13 14:56:53.000000', NULL, 1),
(2147621, 292403, 52578, '<td valign="top">Too much blur everywhere imo, with the rider sharper could''ve been really effective.</td>', 'Too much blur everywhere imo, with the rider sharper could''ve been really effective.', '2006-02-13 14:59:12.000000', NULL, 1),
(2147624, 292573, 52578, '<td valign="top">Great picture and great title... shame you can''t see the goalie though which would''ve added even more.</td>', 'Great picture and great title... shame you can''t see the goalie though which would''ve added even more.', '2006-02-13 14:59:32.000000', NULL, 1),
(2147830, 292775, 19066, '<td valign="top">Excellent clarity of the main subject and one of the best examples of this difficult technique in the bunch.  I hope that the effect is real (that''s a compliment!)... :)</td>', 'Excellent clarity of the main subject and one of the best examples of this difficult technique in the bunch.  I hope that the effect is real (that''s a compliment!)... :)', '2006-02-13 16:49:24.000000', NULL, 1),
(2147833, 290609, 19066, '<td valign="top">Nice.  In addition to getting the technique down quite well (sharp main element and blurred motion background), the bright yellow color of the subject really makes the image pop.</td>', 'Nice.  In addition to getting the technique down quite well (sharp main element and blurred motion background), the bright yellow color of the subject really makes the image pop.', '2006-02-13 16:51:01.000000', NULL, 1),
(2147854, 289925, 19066, '<td valign="top">You nailed the technique.  Perfect shot.  10!</td>', 'You nailed the technique.  Perfect shot.  10!', '2006-02-13 16:58:05.000000', NULL, 1),
